fn append_flip_bit_inductive(pre: Self, post: Self, node_id: NodeId, deposited: StoredType<DT>) {
    let cur = match pre.combiner[node_id] {
        CombinerState::Appending { cur_idx, tail } => cur_idx,
        _ => 0,
    };
    let tail = match pre.combiner[node_id] {
        CombinerState::Appending { cur_idx, tail } => tail,
        _ => 0,
    };
    let phys = log_entry_idx(cur as int, pre.buffer_size);

    assert forall |i, j| post.combiner.contains_key(i) && post.combiner.contains_key(j)
        && i != j implies post.combiner[i].no_overlap_with(post.combiner[j]) by {
        if i == node_id {
            assert(pre.combiner.contains_key(j));
            assert(pre.combiner[j].no_overlap_with(pre.combiner[node_id]));
            if post.combiner[j].is_Reading() {
                assert(post.combiner[j].get_Reading_0().is_Guard());
                let r = post.combiner[j].get_Reading_0();
                assert(post.combiner[node_id].get_Appending_cur_idx() > r.get_Guard_cur()
                    || post.combiner[node_id].get_Appending_tail() <= r.get_Guard_cur());
            } else if post.combiner[j].is_Appending() {
                assert(post.combiner[node_id].get_Appending_cur_idx() >= post.combiner[j].get_Appending_tail()
                    || post.combiner[node_id].get_Appending_tail() <= post.combiner[j].get_Appending_cur_idx());
            }
        } else if j == node_id {
            assert(pre.combiner.contains_key(i));
            if post.combiner[i].is_Appending() {
                assert(post.combiner[i].get_Appending_cur_idx() >= post.combiner[node_id].get_Appending_tail()
                    || post.combiner[i].get_Appending_tail() <= post.combiner[node_id].get_Appending_cur_idx());
            }
        } else {
            assert(pre.combiner[i].no_overlap_with(pre.combiner[j]));
        }
    };

    let min_local_head = map_min_value(post.local_versions, (post.num_replicas - 1) as nat);
    assert forall |i| post.tail <= i < min_local_head + post.buffer_size
        implies !log_entry_is_alive(post.alive_bits, i, post.buffer_size) by {
        if log_entry_idx(i, post.buffer_size) != phys {
            assert(post.alive_bits[log_entry_idx(i, post.buffer_size)]
                == pre.alive_bits[log_entry_idx(i, post.buffer_size)]);
            assert(!log_entry_is_alive(pre.alive_bits, i, pre.buffer_size));
        } else {
            assert(cur < i);
            assert(i < cur + post.buffer_size);
            assert(i == cur + post.buffer_size);
            log_entry_alive_value_wrap_around(cur as int, post.buffer_size);
        }
    };
}

