    #[inductive(advance_tail_finish)]
    fn advance_tail_finish_inductive(pre: Self, post: Self, node_id: NodeId, new_tail: nat) { admit(); }

    #[inductive(append_flip_bit)]
    fn append_flip_bit_inductive(pre: Self, post: Self, node_id: NodeId, deposited: StoredType<DT>) {
        let cur = match pre.combiner[node_id] {
            CombinerState::Appending { cur_idx, tail } => cur_idx,
            _ => 0,
        };
        let tail = match pre.combiner[node_id] {
            CombinerState::Appending { cur_idx, tail } => tail,
            _ => 0,
        };
        let phys = log_entry_idx(cur as int, pre.buffer_size);

        assert forall |i, j| post.combiner.contains_key(i) && post.combiner.contains_key(j)
            && i != j implies post.combiner[i].no_overlap_with(post.combiner[j]) by {
            if i == node_id {
                assert(pre.combiner.contains_key(j));
                assert(pre.combiner[j].no_overlap_with(pre.combiner[node_id]));
                match post.combiner[j] {
                    CombinerState::Reading(ReaderState::Guard { cur: reader_cur, .. }) => {
                        assert(post.combiner[node_id].get_Appending_cur_idx() > reader_cur
                            || post.combiner[node_id].get_Appending_tail() <= reader_cur);
                    },
                    CombinerState::Appending { cur_idx: other_cur, tail: other_tail } => {
                        assert(post.combiner[node_id].get_Appending_cur_idx() >= other_tail
                            || post.combiner[node_id].get_Appending_tail() <= other_cur);
                    },
                    _ => { }
                }
            } else if j == node_id {
                assert(pre.combiner.contains_key(i));
                match post.combiner[i] {
                    CombinerState::Appending { cur_idx: other_cur, tail: other_tail } => {
                        assert(pre.combiner[i].no_overlap_with(pre.combiner[node_id]));
                        assert(other_cur >= tail || other_tail <= cur);
                        assert(other_cur >= tail || other_tail <= cur + 1);
                    },
                    _ => { }
                }
            } else {
                assert(pre.combiner[i].no_overlap_with(pre.combiner[j]));
            }
        };

        let min_local_head = map_min_value(post.local_versions, (post.num_replicas - 1) as nat);
        assert forall |i| post.tail <= i < min_local_head + post.buffer_size
            implies !log_entry_is_alive(post.alive_bits, i, post.buffer_size) by {
            if log_entry_idx(i, post.buffer_size) != phys {
                assert(post.alive_bits[log_entry_idx(i, post.buffer_size)]
                    == pre.alive_bits[log_entry_idx(i, post.buffer_size)]);
                assert(!log_entry_is_alive(pre.alive_bits, i, pre.buffer_size));
            } else {
                assert(cur < i);
                assert(i < cur + post.buffer_size);
                map_min_value_smallest(post.local_versions, (post.num_replicas - 1) as nat);
                assert(0 <= node_id < post.num_replicas);
                assert(map_min_value(post.local_versions, (post.num_replicas - 1) as nat)
                    <= post.local_versions[node_id]);
                assert(post.local_versions[node_id] <= cur);
                assert(i < cur + post.buffer_size);
                assert(false);
            }
        };
    }

    #[inductive(append_finish)]
    fn append_finish_inductive(pre: Self, post: Self, node_id: NodeId) { admit(); }

    #[inductive(reader_start)]
    fn reader_start_inductive(pre: Self, post: Self, node_id: NodeId) { admit(); }

    #[inductive(reader_enter)]
    fn reader_enter_inductive(pre: Self, post: Self, node_id: NodeId) { admit(); }

    #[inductive(reader_guard)]
    fn reader_guard_inductive(pre: Self, post: Self, node_id: NodeId) { admit(); }

