        reveal(CyclicBuffer::State::combiner_valid);
        reveal(CyclicBuffer::State::reader_state_valid);
        assert(pre.combiner[node_id] == CombinerState::Appending { cur_idx: cur, tail });
        assert forall |n| post.combiner.contains_key(n) implies
            post.combiner_valid(n, post.combiner[n]) by {
            if n == node_id {
                assert(pre.combiner_valid(n, pre.combiner[n]));
                assert(pre.local_versions[n] <= cur);
                assert(cur < tail);
                assert(cur + 1 <= tail);
                assert((post.tail as int) - (post.buffer_size as int) <= cur + 1);
                assert forall |i: nat| cur + 1 <= i < tail implies
                    !log_entry_is_alive(post.alive_bits, i as int, post.buffer_size) by {
                    assert(pre.combiner_valid(node_id, pre.combiner[node_id]));
                    assert(!log_entry_is_alive(pre.alive_bits, i as int, pre.buffer_size));
                    assert(0 <= i);
                    assert(cur <= i);
                    assert(i < cur + post.buffer_size);
                    log_entry_idx_wrap_around(cur, post.buffer_size, i);
                    assert(log_entry_idx(i as int, post.buffer_size) != phys);
                }
            } else {
                assert(post.combiner[n] == pre.combiner[n]);
                assert(pre.combiner_valid(n, pre.combiner[n]));
            }
        };

        assert forall |n| n != node_id && post.combiner.contains_key(n) implies
            post.combiner[n] == pre.combiner[n] by {
        };
        assert forall |n| post.combiner.contains_key(n) && post.combiner[n].is_Reading()
            implies post.reader_state_valid(n, post.combiner[n].get_Reading_0()) by {
            if n == node_id {
                assert(!post.combiner[node_id].is_Reading());
            } else {
                assert(post.combiner[n] == pre.combiner[n]);
                assert(pre.reader_state_valid(n, pre.combiner[n].get_Reading_0()));
            }
        };

        let min_local_head = map_min_value(post.local_versions, (post.num_replicas - 1) as nat);
        assert forall |i| post.tail <= i < min_local_head + post.buffer_size
            implies !log_entry_is_alive(post.alive_bits, i, post.buffer_size) by {
            if log_entry_idx(i, post.buffer_size) != phys {
                assert(post.alive_bits[log_entry_idx(i, post.buffer_size)]
                    == pre.alive_bits[log_entry_idx(i, post.buffer_size)]);
                assert(!log_entry_is_alive(pre.alive_bits, i, pre.buffer_size));
            } else {
                assert(post.tail <= i);
                assert(cur < post.tail);
                assert(cur <= i);
                assert(0 <= i);
                assert(i < cur + post.buffer_size);
                map_min_value_smallest(post.local_versions, (post.num_replicas - 1) as nat);
                assert(0 <= node_id < post.num_replicas);
                assert(map_min_value(post.local_versions, (post.num_replicas - 1) as nat)
